BEGIN;
CREATE TABLE IF NOT EXISTS hr_attendance_import_batch(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,batch_code varchar(64) NOT NULL,source_system varchar(64) NOT NULL,source_checksum varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'imported',is_historical_import boolean NOT NULL DEFAULT true,create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_attendance_batch_checksum CHECK(source_checksum~'^[0-9a-f]{64}$'),CONSTRAINT ck_hr_attendance_batch_status CHECK(status IN('imported','verified','failed','rolled_back')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_attendance_batch_code ON hr_attendance_import_batch(tenant_id,park_id,batch_code) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_attendance_calendar_source(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,import_batch_id uuid NOT NULL REFERENCES hr_attendance_import_batch(id),legacy_id integer NOT NULL,calendar_name varchar(100),calendar_year integer NOT NULL,calendar_month integer NOT NULL,source_snapshot jsonb NOT NULL DEFAULT'{}',create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_attendance_calendar_period CHECK(calendar_year BETWEEN 1900 AND 2100 AND calendar_month BETWEEN 1 AND 12));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_attendance_calendar_legacy ON hr_attendance_calendar_source(tenant_id,park_id,legacy_id) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_attendance_day(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,calendar_source_id uuid NOT NULL REFERENCES hr_attendance_calendar_source(id),attendance_date date NOT NULL,legacy_symbol varchar(64),symbol_status varchar(32) NOT NULL,normalized_kind varchar(32),is_historical_import boolean NOT NULL DEFAULT true,create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_attendance_symbol_status CHECK(symbol_status IN('mapped','blank','needs_review')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_attendance_day_source_date ON hr_attendance_day(tenant_id,park_id,calendar_source_id,attendance_date) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_insurance_policy(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,policy_code varchar(64) NOT NULL,policy_name varchar(200),scope_description varchar(500),status varchar(32) NOT NULL DEFAULT'historical',is_historical_import boolean NOT NULL DEFAULT true,create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_insurance_policy_code ON hr_insurance_policy(tenant_id,park_id,policy_code) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_insurance_policy_item(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,policy_id uuid NOT NULL REFERENCES hr_insurance_policy(id),insurance_kind varchar(32) NOT NULL,variant_no integer NOT NULL DEFAULT 1,base_rate numeric(18,6),employer_rate numeric(18,6),employee_rate numeric(18,6),supplement_rate numeric(18,6),source_snapshot jsonb NOT NULL DEFAULT'{}',create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_insurance_policy_rates CHECK((base_rate IS NULL OR base_rate>=0)AND(employer_rate IS NULL OR employer_rate>=0)AND(employee_rate IS NULL OR employee_rate>=0)AND(supplement_rate IS NULL OR supplement_rate>=0)));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_insurance_policy_item ON hr_insurance_policy_item(tenant_id,park_id,policy_id,insurance_kind,variant_no) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_employee_insurance_period(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,employee_id uuid NOT NULL REFERENCES hr_employee(id),period_year integer NOT NULL,period_month integer NOT NULL,legacy_id integer NOT NULL,status varchar(32) NOT NULL DEFAULT'historical',needs_review boolean NOT NULL DEFAULT false,is_historical_import boolean NOT NULL DEFAULT true,source_snapshot jsonb NOT NULL DEFAULT'{}',create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_employee_insurance_period CHECK(period_year BETWEEN 1900 AND 2100 AND period_month BETWEEN 1 AND 12));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_employee_insurance_month ON hr_employee_insurance_period(tenant_id,park_id,employee_id,period_year,period_month) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS hr_employee_insurance_item(id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,period_id uuid NOT NULL REFERENCES hr_employee_insurance_period(id),insurance_kind varchar(32) NOT NULL,contribution_base numeric(18,2),total_amount numeric(18,2),employer_amount numeric(18,2),employee_amount numeric(18,2),supplement_amount numeric(18,2),legacy_base_negative boolean NOT NULL DEFAULT false,create_by uuid,create_time timestamptz NOT NULL DEFAULT now(),update_by uuid,update_time timestamptz NOT NULL DEFAULT now(),is_deleted boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,remark varchar(500),CONSTRAINT ck_hr_employee_insurance_amounts CHECK((contribution_base IS NULL OR contribution_base>=0)AND(total_amount IS NULL OR total_amount>=0)AND(employer_amount IS NULL OR employer_amount>=0)AND(employee_amount IS NULL OR employee_amount>=0)AND(supplement_amount IS NULL OR supplement_amount>=0)));
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_employee_insurance_item ON hr_employee_insurance_item(tenant_id,park_id,period_id,insurance_kind) WHERE is_deleted=false;
COMMIT;
